export const QUIZ_CATEGORIES: QuizCategory[] = Array.from(new Set(QUIZ_CARDS.map((c) => c.category))).sort();

// Random card excluding recently-used ids (mirrors nextTextPrompt's exclude pattern).
export function randomQuizCard(exclude?: string | null, used?: string[]): QuizCard {
  const usedSet = new Set(used ?? []);
  const fresh = QUIZ_CARDS.filter((c) => c.id !== exclude && !usedSet.has(c.id));
  const pool = fresh.length > 0 ? fresh : QUIZ_CARDS;
  return pool[Math.floor(Math.random() * pool.length)];
}

// Shuffled 4 options + index of the correct answer. Classic mode uses this;
// bluff mode ignores `options` and shuffles player fakes + answer instead.
export function shuffledChoicesFor(card: QuizCard): { options: string[]; correctIndex: number } {
  const options = [card.answer, ...card.incorrect];
  for (let i = options.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [options[i], options[j]] = [options[j], options[i]];
  }
  return { options, correctIndex: options.indexOf(card.answer) };
}

export const QUIZ_COUNT = QUIZ_CARDS.length;
